svg.script:
function cover(id, offset) {
  let element = document.getElementById(id);
  element.dx.baseVal[0].value = offset;
  let rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
  let bbox = element.getBBox();
  // Inflate by a couple pixels, to prevent antialiasing failures.
  rect.x.baseVal.value = bbox.x - 2;
  rect.y.baseVal.value = bbox.y - 2;
  rect.width.baseVal.value = bbox.width + 4;
  rect.height.baseVal.value = bbox.height + 4;
  element.parentElement.appendChild(rect);
}
onload = function() {
  document.fonts.ready.then(() => {
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    ctx.font = '30px test';

    // The covering text uses the text-before-edge baseline, so it has to
    // move by the distance between that baseline and the one it covers, that
    // is, (ascent + descent) minus what GetBaselinePosition() returns in
    // layout/svg/SVGTextFrame.cpp. Note that in vertical-rl that function
    // mirrors most of the baselines it computes (convertIfVerticalRL).
    //
    // gfxFont::CreateVerticalMetrics() synthesizes vertical metrics with a
    // centered baseline out of the horizontal ascent and descent, so the
    // ascent and the descent of vertical text are each half of the block
    // size.
    let metrics = ctx.measureText('h');
    let blockSize =
      metrics.fontBoundingBoxAscent + metrics.fontBoundingBoxDescent;
    let ascent = blockSize / 2;

    // ascent * 0.5, not mirrored.
    cover("alphabetic", blockSize - 0.5 * ascent);

    // Mirrored logical baseline, which is the ascent.
    cover("auto", ascent);

    // Same, minus half the x-height. The vertical metrics x-height is small
    // enough for the covering rect to still cover the text.
    cover("middle", ascent);

    // Mirrored ascent * 0.2.
    cover("hanging", 0.2 * ascent);

    // (ascent + descent) / 2, not mirrored.
    cover("central", blockSize / 2);

    // Mirrored ascent / 2.
    cover("mathematical", ascent / 2);

    cover("text-bottom", blockSize);

    document.documentElement.removeAttribute('class');
  });
}
